<script setup lang="ts">import {nextTick,onMounted,useTemplateRef,watch} from "vue";import MessageBubble from "./MessageBubble.vue";import type {Message} from "../types/message.ts";const props=defineProps<{messages:Message[];currentUserId:number}>();const emit=defineEmits<{delete:[messageId:number]}>();const bottomAnchor=useTemplateRef<HTMLDivElement>("bottom-anchor");async function scrollToBottom(){await nextTick();bottomAnchor.value?.scrollIntoView({behavior:"smooth",block:"end"})}watch(()=>props.messages.length,scrollToBottom);onMounted(scrollToBottom)</script>
<template><div class="messages"><div class="messages-inner"><div v-if="messages.length===0" class="empty"><strong>Здесь пока пусто</strong><span>Напишите первое сообщение</span></div><MessageBubble v-for="message in messages" :key="message.id" :message="message" :is-own="message.author_id===currentUserId" @delete="emit('delete',$event)"/><div ref="bottom-anchor" class="bottom-anchor" aria-hidden="true"></div></div></div></template>
<style scoped>.messages{flex:1;overflow-y:auto;padding:24px;background:var(--bg)}.messages-inner{min-height:100%;display:flex;flex-direction:column;justify-content:flex-end;gap:10px}.empty{margin:auto;display:flex;flex-direction:column;gap:6px;text-align:center;color:var(--muted)}.bottom-anchor{height:1px;flex-shrink:0}</style>
